pts=[(r,c) for r,row in enumerate(demo) for c,v in enumerate(row) if v==5]
def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
def hull(points):
 p=sorted(set(points)); lo=[]; hi=[]
 for x in p:
  while len(lo)>=2 and cross(lo[-2],lo[-1],x)<=0: lo.pop()
  lo.append(x)
 for x in reversed(p):
  while len(hi)>=2 and cross(hi[-2],hi[-1],x)<=0: hi.pop()
  hi.append(x)
 return lo[:-1]+hi[:-1]
h=hull(pts); h

def inside(p,h):
 vals=[cross(h[i],h[(i+1)%len(h)],p) for i in range(len(h))]
 return all(v>=0 for v in vals) or all(v<=0 for v in vals)
